import{_ as d,a0 as r,w as i,s as l,ao as a,I as n,x as t,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"tespeed - 測試網速的Python工具 | LCTT x X-CMD","titleTemplate":false,"description":"tespeed - 測試網速的Python工具 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"tespeed - 測試網速的Python工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"tespeed - 測試網速的Python工具 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150202 tespeed - Python Tool To Test Your Internet Speed","title":"tespeed - 測試網速的Python工具","tag":"201504","desc":""},"relativePath":"201504/20150202 tespeed - Python Tool To Test Your Internet Speed.md","filePath":"[post].md"}'),h={name:"201504/20150202 tespeed - Python Tool To Test Your Internet Speed.md"};function g(m,e,y,u,T,x){const p=r("Link");return i(),l("div",null,[e[13]||(e[13]=a(`<h1 id="tespeed-測試網速的python工具" tabindex="-1">tespeed - 測試網速的Python工具 <a class="header-anchor" href="#tespeed-測試網速的python工具" aria-label="Permalink to “tespeed - 測試網速的Python工具”">​</a></h1><p>許多電腦呆子知道可以用<strong>speedtest.net</strong>測試網速，但是這個不能在測試中給你足夠的控制。Linux用户喜歡在終端中輸入命令來完成任務，至少我就是這樣的。</p><p>tespeed是一款有很多特性的python工具，可以在終端在測試網速。根據文檔説明，它利用了speedtest.net的服務器，但是用户可以手動指定。</p><p>最初作者用php語言寫了tespeed工具，並且證明了ISP提供的網絡遠低於它廣告中所説的那樣。但是事情並不是一直如他們想的那樣，因此作者移植他的php腳本到python中，並且他的工具在github中已經有180個star了。</p><p>It means <strong>alot</strong>。</p><h3 id="如何在linux中測試tespeed" tabindex="-1">如何在linux中測試tespeed <a class="header-anchor" href="#如何在linux中測試tespeed" aria-label="Permalink to “如何在linux中測試tespeed”">​</a></h3><p>在你電腦上運行這個python程序前先確保系統已經滿足了這個工具的依賴。tespeed依賴下面兩個包：</p><ul><li>lxml</li><li>SocksiPy</li></ul><p>你可以用pip包管理系統來安裝lxml，只要用下面的命令就行。</p><pre><code>pip install lxml
</code></pre><p>現在我們需要輸入下面的命令來下載安裝SocksiPy。</p><pre><code>wget http://sourceforge.net/projects/socksipy/files/socksipy/SocksiPy%201.00/SocksiPy.zip/
</code></pre><p>下載完成後 解壓<strong>SocksiPy.zip</strong>並運行下面的命令來克隆tespeed倉庫到你本地機器中。</p><pre><code>git clone https://github.com/Janhouse/tespeed.git
</code></pre><p>接着把SocksiPy文件夾放到你克隆下來的tespeed項目中。現在我們要像截圖那樣在SocksiPy中的創建一個叫<strong><strong>init</strong>.py</strong>的空文件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/tespeed1.png" alt="simple trick to make tespeed work"></p><p>現在我們已經解決了項目的依賴問題，我們可以用下面的命令運行了。</p><pre><code>python tespeed.py
</code></pre><p>接下來就會發生一些神奇的事了。程序會測試你的下載和上傳速度並且在你的終端中用漂亮的顏色顯示出來。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/tespeed2.png" alt="testing download and upload speed with tespeed python application"></p><p>在tespeed中有很多選項，如<strong>-ls</strong>來列出服務器，<strong>-p</strong>來指定代理服務器， <strong>-s</strong>來阻止調試(STDERR)輸出, 還有很多我們會在本教程中探索。</p><p>如果你想要結果顯示成MB，你可以在<strong>python tespeed.py</strong> 後面接上選項 <strong>-mib</strong>。</p><pre><code>python tespeed.py -mib
</code></pre><p>在你使用了-mib選項後你可以看到計量網速的單位改變了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/tespeed3.png" alt="testing internet speed with tespeed python application"></p><p>我非常喜歡用的一個選項是-w，它可以把標準輸出轉化成CSV格式。</p><pre><code>python tespeed.py -w
</code></pre><p>使用下面的命令來列出服務器。</p><pre><code>python tespeed -ls
</code></pre><p>運行上面的命令後，你會看到可以用於測試上傳和下載速度的服務器列表。我的列表非常長，所以我不會在教程中共享了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>tespeed的確是一款幫助用户在終端中測試上傳和下載速度的高性能python腳本。它支持很多的選項並且你可以指定列表中你想使用的服務器。繼續使用tespeed並在留言區寫下你們的體驗吧。</p><hr>`,33)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),o(p,{href:"http://linoxide.com/tools/tespeed-python-tool-test-internet-speed/"},{default:s(()=>[...e[0]||(e[0]=[t("http://linoxide.com/tools/tespeed-python-tool-test-internet-speed/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=t("作者：",-1)),o(p,{href:"http://linoxide.com/author/oltjano/"},{default:s(()=>[...e[2]||(e[2]=[t("Oltjano Terpollari",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:s(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),o(p,{href:"http://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const k=d(h,[["render",g]]);export{c as __pageData,k as default};
